// The shop brief in the system prompt (docs/angebot.md §6.3): the shop's facts, from confirmed
// content only. The text is generated by scripts/build-brief.mjs into brief.generated.ts (committed,
// checked for drift by test/brief.test.ts); this module only wraps it for the prompt.
//
// While the owner has confirmed nothing, the brief says so section by section („Keine bestätigten
// Angaben.“) and lists only the configurator's project types; the prompt tells Claude not to fill
// the gaps (prompts.ts). Each confirmation in src/content enters the brief on the next `npm run brief`.
import { SHOP_BRIEF } from './brief.generated';

export { SHOP_BRIEF };

/** The brief as a delimited block for the system prompt. */
export const briefBlock = (): string => `<betrieb>\n${SHOP_BRIEF.trimEnd()}\n</betrieb>`;
